#include <stdio.h>



int main(void) {
    double profit, bonus = 0;
    double limits[] = {100000, 200000, 400000, 600000, 1000000};
    double rates[] = {0.10, 0.075, 0.05, 0.03, 0.015, 0.01};
    scanf("%lf", &profit);
    double previous = 0;
    for (int i = 0; i < 5 && profit > previous; i++) {
        double end = profit < limits[i] ? profit : limits[i];
        bonus += (end - previous) * rates[i];
        previous = end;
    }
    if (profit > 1000000) bonus += (profit - 1000000) * rates[5];
    printf("%.2f\n", bonus);
    return 0;
}
